    <div class="cl-stage">
      <figure><figcaption>Camera view \xB7 what the audience sees</figcaption><div class="cl-box shot"><div class="hud"><div class="g"></div><div class="br"></div><span class="rec">\u25CF REC</span><span class="tc">00:00:00</span><span class="nm"></span><span class="mm"></span><button class="cl-play" aria-label="Play the move">\u25B6</button></div></div></figure>
      <figure><figcaption>On set \xB7 how the camera moves</figcaption><div class="cl-box set"></div></figure>
    </div>
